#!/usr/bin/env node
/*!
 * build-standalone-demo — generate the all-in-one demo from the split one.
 *
 * The demo ships in two shapes, one source of truth:
 *
 *   demo/index.html       the SPLIT version — the recommended project layout:
 *                         it <link>s ../letterbox.css and loads the plugin from
 *                         ../reveal-autohide-toolbar.js. Edit THIS file.
 *   demo/standalone.html  the ALL-IN-ONE version — GENERATED by this tool: the
 *                         letterbox stylesheet and the plugin are inlined so the
 *                         single file runs anywhere you drop it (shared libs —
 *                         reveal, fonts, math — still load from a CDN).
 *
 * Keeping standalone.html generated means the two can never drift: change
 * letterbox.css or the deck once, rebuild, and both stay in step.
 *
 * Usage:
 *   node tools/build-standalone-demo.mjs           write demo/standalone.html
 *   npm run build:standalone
 *   node tools/build-standalone-demo.mjs --check    verify it's up to date
 *                                                    (exit 1 if stale/missing);
 *                                                    writes nothing — for CI
 *   -h, --help
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, relative } from 'node:path';

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const SRC       = join(repoRoot, 'demo', 'index.html');
const OUT       = join(repoRoot, 'demo', 'standalone.html');
const LETTERBOX = join(repoRoot, 'letterbox.css');
const PLUGIN    = join(repoRoot, 'reveal-autohide-toolbar.js');

// The two local dependencies the split demo pulls from the repo root, and the
// exact markup that loads each. Matched literally so a structural change in the
// source fails loudly here rather than emitting a half-inlined file.
const LINK   = '<link rel="stylesheet" href="../letterbox.css" />';
const SCRIPT = '<script src="../reveal-autohide-toolbar.js"></script>';

const BANNER = `<!--
  ⚠ GENERATED FILE — do not edit by hand.
  All-in-one build of the demo: letterbox.css and the autohide-toolbar plugin
  are inlined so this single file runs anywhere you drop it. Shared libraries
  (reveal.js, fonts, MathJax) still load from a CDN.
  Source of truth: demo/index.html (+ letterbox.css + reveal-autohide-toolbar.js).
  Regenerate:  npm run build:standalone
-->`;

// A literal replace that asserts the needle exists — a missing marker means the
// source drifted and the build must not silently produce broken output.
function replaceOrThrow(haystack, needle, replacement, what) {
  if (!haystack.includes(needle)) {
    throw new Error(
      `build-standalone-demo: could not find ${what} in demo/index.html\n` +
      `  looked for: ${needle}\n` +
      `  the split demo's structure changed — update this tool to match.`);
  }
  return haystack.replace(needle, replacement);
}

// '</script' anywhere in the plugin source (it appears in comments/strings) would
// prematurely close the inline <script>; escape it the standard way.
const escapeForScript = js => js.replace(/<\/script/gi, '<\\/script');

function build() {
  let html = readFileSync(SRC, 'utf8');
  const css = readFileSync(LETTERBOX, 'utf8').trimEnd();
  const js  = readFileSync(PLUGIN, 'utf8');

  html = replaceOrThrow(html, LINK,
    `<style>\n/* inlined from letterbox.css — edit that file, not this one */\n${css}\n  </style>`,
    'the letterbox <link>');

  html = replaceOrThrow(html, SCRIPT,
    `<script>\n/* inlined from reveal-autohide-toolbar.js — edit that file, not this one */\n${escapeForScript(js)}\n</script>`,
    'the plugin <script>');

  // Stamp the "don't edit" banner right after the doctype.
  html = replaceOrThrow(html, '<!doctype html>', `<!doctype html>\n${BANNER}`,
    'the doctype');

  return html;
}

const args = new Set(process.argv.slice(2));
if (args.has('-h') || args.has('--help')) {
  console.log(readFileSync(fileURLToPath(import.meta.url), 'utf8')
    .split('\n').filter(l => l.startsWith(' *')).map(l => l.slice(3)).join('\n'));
  process.exit(0);
}

const out = build();
const rel = relative(repoRoot, OUT);

if (args.has('--check')) {
  let current = null;
  try { current = readFileSync(OUT, 'utf8'); } catch { /* missing */ }
  if (current === out) {
    console.log(`✓ ${rel} is up to date`);
    process.exit(0);
  }
  console.error(`✗ ${rel} is stale or missing — run: npm run build:standalone`);
  process.exit(1);
}

writeFileSync(OUT, out);
console.log(`✓ wrote ${rel} (${(out.length / 1024).toFixed(0)} KB, all-in-one)`);
